236	func Push(ctx context.Context, remote, refSpec string) (PushResult, error) {
237		return PushWithOptions(ctx, PushOptions{
238			Remote:   remote,
239			RefSpecs: []string{refSpec},
240		})
241	}
242	
243	// PushWithOptions runs git push --no-verify --porcelain with token injection.
244	// GIT_TERMINAL_PROMPT=0 is always set.
245	func PushWithOptions(ctx context.Context, opts PushOptions) (PushResult, error) {
246		pushTarget, err := resolvePushCommandTarget(ctx, opts.Remote)
247		if err != nil {
248			return PushResult{}, fmt.Errorf("resolve push target: %w", err)
249		}
250	
251		args := []string{"push", "--no-verify", "--porcelain"}
252		args = append(args, opts.ExtraArgs...)
253		args = append(args, pushTarget)
254		args = append(args, opts.RefSpecs...)
255	
256		cmd := newCommand(ctx, args...)
257		if opts.Dir != "" {
258			cmd.Dir = opts.Dir
259		}
260		disableTerminalPrompt(cmd)
261		output, err := cmd.CombinedOutput()
262		if err != nil {
263			return PushResult{Output: string(output)}, fmt.Errorf("git push: %w", err)
264		}
265		return PushResult{Output: string(output)}, nil
266	}
267	
268	// LsRemote runs git ls-remote with token injection.
269	// GIT_TERMINAL_PROMPT=0 is always set. Returns stdout only.
270	func LsRemote(ctx context.Context, remote string, patterns ...string) ([]byte, error) {
271		return lsRemote(ctx, "", remote, patterns...)
272	}
273	
274	// LsRemoteInDir is like LsRemote but runs in a specific directory.
275	func LsRemoteInDir(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
276		return lsRemote(ctx, dir, remote, patterns...)
277	}
278	
279	func lsRemote(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
280		args := append([]string{"ls-remote", remote}, patterns...)
281		cmd := newCommand(ctx, args...)
282		if dir != "" {
283			cmd.Dir = dir
284		}
285		disableTerminalPrompt(cmd)
286		out, err := cmd.Output()
287		if err != nil {
288			return out, fmt.Errorf("git ls-remote: %w", err)
289		}
290		return out, nil
291	}
292	
293	// IsURL returns true if the target looks like a URL rather than a git remote name.
294	func IsURL(target string) bool {
295		return strings.Contains(target, "://") || strings.Contains(target, "@")
296	}
297	
298	// ResolveFetchTarget returns the git fetch target to use. When filtered
299	// fetches are enabled, configured remotes are resolved to their URL so git does
300	// not persist promisor settings onto the remote name.
301	func ResolveFetchTarget(ctx context.Context, target string) (string, error) {
302		if IsURL(target) || isLocalPath(target) || !settings.IsFilteredFetchesEnabled(ctx) {
303			return target, nil
304		}
305		url, err := GetRemoteURL(ctx, target)
306		if err != nil {
307			return "", fmt.Errorf("get remote URL: %w", err)
308		}
309		return url, nil
310	}
311	
312	// newCommand creates an exec.Cmd for a git operation that may need
313	// checkpoint token authentication. If ENTIRE_CHECKPOINT_TOKEN is set:
314	//   - if the target in args is (or resolves to) an SSH remote, the target is
315	//     rewritten in the args to the equivalent HTTPS URL so git uses HTTP
316	//     transport and our injected Authorization header applies;
317	//   - a Basic auth token is then injected via GIT_CONFIG_COUNT/GIT_CONFIG_KEY_*/
318	//     GIT_CONFIG_VALUE_* environment variables.
319	//
320	// If rewriting fails (unparseable URL, missing owner/repo) the command runs
321	// unmodified and a one-shot warning is printed.
322	// For empty/unset tokens, the command is returned unmodified.
323	//
324	// The remote is extracted from args by skipping the git subcommand and any flags
325	// (arguments starting with "-"). For example, in
326	// ["push", "--no-verify", "origin", "main"], the remote is "origin".
327	func newCommand(ctx context.Context, args ...string) *exec.Cmd {
328		token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar))
329	
330		mkCmd := func(finalArgs []string) *exec.Cmd {
331			c := exec.CommandContext(ctx, "git", finalArgs...)
332			c.Stdin = nil // Disconnect stdin to prevent hanging in hook context
333			return c
334		}
335	
336		if token == "" {
337			return mkCmd(args)
338		}
339	
340		if !isValidToken(token) {
341			fmt.Fprintf(os.Stderr, "[entire] Warning: %s contains invalid characters (CR, LF, or other control chars) — token ignored\n", CheckpointTokenEnvVar)
342			return mkCmd(args)
343		}
344	
345		target := extractRemoteFromArgs(args)
346		if target == "" {
347			return mkCmd(args)
348		}
349	
350		newTarget, protocol := resolveTargetForTokenAuth(ctx, target)
351		if newTarget != target {
352			args = replaceFirstPositional(args, newTarget)
353		}
354	
355		cmd := mkCmd(args)
356	
357		switch protocol {
358		case ProtocolSSH:
359			sshTokenWarningOnce.Do(func() {
360				fmt.Fprintf(os.Stderr, "[entire] Warning: %s is set but remote uses SSH — token ignored for SSH remotes\n", CheckpointTokenEnvVar)
361			})
362			return cmd
363		case ProtocolHTTPS:
364			cmd.Env = appendCheckpointTokenEnv(os.Environ(), token)
365			return cmd
366		default:
367			// Unknown protocol (e.g., local path, or resolution failed) — don't inject
368			return cmd
369		}
370	}
371	
372	// resolveTargetForTokenAuth resolves a git target (remote name or URL) to its
373	// effective protocol, rewriting SSH targets to the equivalent HTTPS URL so
374	// token-based auth can be applied. Returns the (possibly rewritten) target and
375	// its final protocol. Protocol is "" when resolution fails (local path,
376	// nonexistent remote, unparseable URL).
377	//
378	// This is only meaningful when ENTIRE_CHECKPOINT_TOKEN is set; callers gate on
379	// that themselves.
380	func resolveTargetForTokenAuth(ctx context.Context, target string) (string, string) {
381		if target == "" || isLocalPath(target) {
382			return target, ""
383		}
384	
385		rawURL := target
386		if !IsURL(target) {
387			var err error
388			rawURL, err = GetRemoteURL(ctx, target)
389			if err != nil {
390				return target, ""
391			}
392		}
393	
394		info, err := ParseURL(rawURL)
395		if err != nil {
396			return target, ""
397		}
398	
399		if info.Protocol == ProtocolSSH {
400			if httpsURL, ok := deriveTokenOriginURL(rawURL); ok {
401				return httpsURL, ProtocolHTTPS
402			}
403			return target, ProtocolSSH
404		}
405	
406		return target, info.Protocol
407	}
408	
409	// replaceFirstPositional returns a copy of args with the first non-flag
410	// argument after args[0] (the git subcommand) replaced by newTarget. Callers
411	// use this to rewrite a remote name/URL after resolution without mutating the
412	// original slice.
413	func replaceFirstPositional(args []string, newTarget string) []string {
414		out := make([]string, len(args))
415		copy(out, args)
416		for i := 1; i < len(out); i++ {
417			if !strings.HasPrefix(out[i], "-") {
418				out[i] = newTarget
419				return out
420			}
421		}
422		return out
423	}
424	
425	// extractRemoteFromArgs finds the remote URL or name from git command args.
426	// It skips the subcommand (first arg) and any flags (args starting with "-"),
427	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
428	func extractRemoteFromArgs(args []string) string {
429		if len(args) < 2 {
430			return ""
431		}
432		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
433		for _, arg := range args[1:] {
434			if !strings.HasPrefix(arg, "-") {
435				return arg
436			}
437		}
438		return ""
439	}
440	
441	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
442	// an Authorization header into git HTTP requests. The token is sent as a Basic
443	// credential with the format "x-access-token:<token>" (base64-encoded), which
444	// is compatible with GitHub's token authentication.
445	//
446	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
447	// http.extraHeader entry is appended at the next free index and
448	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
449	// config (e.g., safe.directory, custom CA settings) intact.
450	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
451		existingCount := 0
452		for _, e := range baseEnv {
453			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
454			if !ok {
455				continue
456			}
457			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
458				existingCount = n
459			}
460		}
461	
462		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
463		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
464		filtered := make([]string, 0, len(baseEnv)+3)
465		for _, e := range baseEnv {
466			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
467				continue
468			}
469			filtered = append(filtered, e)
470		}
471	
472		idx := existingCount
473		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
474		return append(filtered,
475			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
476			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
477			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
478		)
479	}
480	
481	// isValidToken returns false if the token contains control characters (bytes < 0x20
482	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
483	// embedded in the token value.
484	func isValidToken(token string) bool {
485		for _, b := range []byte(token) {
486			if b < 0x20 || b == 0x7F {
487				return false
488			}
489		}
490		return true
491	}
492	
493	// resolvePushCommandTarget returns the target to pass to git push. When a
494	// dedicated checkpoint_remote is configured, the checkpoint URL is returned so
495	// the push is routed to the separate checkpoint repo. Otherwise the remote
496	// name is returned unchanged so git uses its own config, updates the
497	// refs/remotes/<name>/<branch> tracking ref, and subsequent calls can use that
498	// tracking ref to skip redundant pushes.
499	//
500	// SSH→HTTPS coercion for token auth is handled by newCommand, which rewrites
501	// the command args or injects per-host config, rather than being baked into
502	// the target here.
503	func resolvePushCommandTarget(ctx context.Context, target string) (string, error) {
504		if target == "" || IsURL(target) || isLocalPath(target) {
505			return target, nil
506		}
507	
508		pushTarget, enabled, err := PushURL(ctx, target)
509		if err != nil {
510			return "", err
511		}
512		if !enabled || pushTarget == "" {
513			return target, nil
514		}
515		return pushTarget, nil
516	}
517	
518	func isLocalPath(target string) bool {
519		return filepath.IsAbs(target) || strings.HasPrefix(target, "./") || strings.HasPrefix(target, "../")
520	}
521	
522	// disableTerminalPrompt sets GIT_TERMINAL_PROMPT=0 on the command,
523	// initializing cmd.Env from os.Environ() if nil.
524	func disableTerminalPrompt(cmd *exec.Cmd) {
525		if cmd.Env == nil {
526			cmd.Env = os.Environ()
527		}
528		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
529	}
